mapper.update:
UPDATE notification.notification
   SET status = #{status},
       sent_at = #{sentAt},
       failure_reason = #{failureReason}
 WHERE id = #{id}
   AND status = 'PENDING'

mapper.select:
SELECT id, event_id, recipient_user_id, email, kind, target_ref, locale, status, sent_at, failure_reason,
       created_at
  FROM notification.notification
 WHERE event_id = #{eventId}
   AND recipient_user_id = #{recipientUserId}
